const PRODUCT_COLORS = ["#d7c0a2", "#b9d7a2", "#f0c986", "#f2c1a3", "#b79a83", "#c99e83", "#e9aab6", "#b3b6d9", "#d6a16f", "#a9c7bf"];

function POSPaymentModal({ open, onClose, total, baseCurrency = "USD", currencies = [], rates = [], tenders, setTenders, changeCurrency, setChangeCurrency, onConfirm, loading, error, pendingPayment, onCompleteMock }) {  const currencyCodes = [...new Set([baseCurrency, ...currencies.map((item) => item.code || item.currency?.code).filter(Boolean)])];  const tenderedBase = tenders.reduce((sum, tender) => sum + (amountToBaseCurrency(tender.amount, tender.currency_code, rates, baseCurrency) || 0), 0);  const changeBase = Math.max(0, tenderedBase - total);  const changeRate = amountForCurrency(1, changeCurrency, rates, baseCurrency);  const changeAmount = changeCurrency === baseCurrency ? changeBase : changeRate === null ? null : changeBase * changeRate;  const hasUnknownRate = tenders.some((tender) => tender.currency_code !== baseCurrency && amountToBaseCurrency(tender.amount, tender.currency_code, rates, baseCurrency) === null && Number(tender.amount) > 0);  const formatTenderCurrency = (code) => code === "KHR" ? "KHR" : code;  const updateTender = (index, field, value) => setTenders((current) => current.map((tender, tenderIndex) => tenderIndex === index ? { ...tender, [field]: value } : tender));  const addTender = () => setTenders((current) => [...current, { method: "cash", currency_code: baseCurrency, amount: "" }]);  const removeTender = (index) => setTenders((current) => current.length === 1 ? current : current.filter((_, tenderIndex) => tenderIndex !== index));  if (pendingPayment) return <Modal open={open} onClose={onClose} title="Waiting for KHQR payment" description="Keep this window open until payment is confirmed." width="max-w-[460px]"><div className="rounded-2xl border border-[#dfe8d7] bg-[#f8fcf5] p-5 text-center"><div className="mx-auto flex h-[188px] w-[188px] items-center justify-center rounded-xl border-[7px] border-white bg-white p-3 shadow-sm"><QRCodeSVG value={pendingPayment.qr_string || pendingPayment.checkout_url || pendingPayment.external_id || "chmaba-payment"} size={158} includeMargin level="H" /></div><div className="mt-4 flex items-center justify-center gap-2"><span className="flex h-5 w-5 items-center justify-center rounded bg-[#ed2939] text-[8px] font-extrabold text-white">KH</span><span className="text-xs font-extrabold text-[#465142]">KHQR</span></div><p className="mt-1 text-[10px] text-[#84907e]">Scan with any Bakong-enabled banking app</p><p className="mt-3 text-[10px] font-semibold text-[#6c7966]">Payment status: {pendingPayment.status || "pending"}</p><p className="mt-4 text-[9px] font-semibold text-[#99a293]">Powered by <span className="text-[#5b6557]">cutluy.com</span></p></div><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Close</Button>{pendingPayment.external_id?.startsWith("mock_") && <Button className="flex-[1.5]" onClick={() => onCompleteMock(pendingPayment)}>Simulate paid <Check size={15} /></Button>}</div></Modal>;  return <Modal open={open} onClose={onClose} title="Complete payment" description="Accept one or more tenders. Chmaba converts each amount to store currency." width="max-w-[520px]"><div className="rounded-xl bg-[#f7f7fa] p-4"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-[#858690]">Amount due · {baseCurrency}</span><span className="text-xl font-extrabold tracking-[-.04em]">{formatCurrencyAmount(total, baseCurrency)}</span></div><div className="mt-2 flex items-center justify-between text-[10px] text-[#92939d]"><span>Tendered in base currency</span><span className={`font-bold ${tenderedBase >= total ? "text-[#66a53d]" : "text-[#b17e20]"}`}>{formatCurrencyAmount(tenderedBase, baseCurrency)}</span></div></div><div className="mt-5 space-y-2">{tenders.map((tender, index) => <div key={`${index}-${tender.currency_code}`} className="rounded-xl border border-[#e7e7ed] bg-white p-3"><div className="flex items-center gap-2"><Dropdown value={tender.method} onChange={(v) => updateTender(index, "method", v)} triggerClass="h-9 rounded-lg border border-[#e1e1e8] bg-white px-2 text-xs font-semibold text-[#292a31] dark:border-[#363740] dark:bg-[#1f2025] dark:text-[#e4e4e8]" options={[{ value: "cash", label: "Cash" }, { value: "card", label: "Card" }, { value: "khqr", label: "KHQR" }]} /><Dropdown value={tender.currency_code} onChange={(v) => updateTender(index, "currency_code", v)} triggerClass="h-9 rounded-lg border border-[#e1e1e8] bg-white px-2 text-xs font-semibold text-[#292a31] dark:border-[#363740] dark:bg-[#1f2025] dark:text-[#e4e4e8]" options={currencyCodes.map((code) => ({ value: code, label: formatTenderCurrency(code) }))} /><input autoFocus={index === tenders.length - 1 && !tender.amount} value={tender.amount} onChange={(event) => updateTender(index, "amount", event.target.value)} type="number" min="0" step={tender.currency_code === "KHR" ? "1" : "0.01"} placeholder={tender.currency_code === "KHR" ? "0" : "0.00"} className="h-9 min-w-0 flex-1 rounded-lg border border-[#e1e1e8] px-3 text-right text-sm font-extrabold outline-none focus:border-[#887bf3]" /><IconButton label="Remove tender" onClick={() => removeTender(index)} disabled={tenders.length === 1}><X size={14} /></IconButton></div>{Number(tender.amount) > 0 && <div className="mt-2 flex justify-between text-[10px] text-[#92939d]"><span>{tender.currency_code} {Number(tender.amount).toLocaleString()} · Rate {tender.currency_code === baseCurrency ? "1" : rates.find((rate) => rate.base_currency_code === baseCurrency && rate.quote_currency_code === tender.currency_code)?.rate || "not set"}</span><span className="font-bold text-[#60616c]">{amountToBaseCurrency(tender.amount, tender.currency_code, rates, baseCurrency) === null ? "Rate required" : `â‰ˆ ${formatCurrencyAmount(amountToBaseCurrency(tender.amount, tender.currency_code, rates, baseCurrency), baseCurrency)}`}</span></div>}</div>)}</div><button onClick={addTender} className="mt-3 flex items-center gap-1.5 text-[11px] font-bold text-[#6957f5] hover:text-[#5040d6]"><Plus size={13} /> Add another tender</button>{changeBase > 0 && <div className="mt-5 rounded-xl border border-[#dfe8d7] bg-[#f7fcf3] p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-extrabold text-[#4a5a43]">Change due</p><p className="mt-1 text-[10px] text-[#82917b]">{formatCurrencyAmount(changeBase, baseCurrency)} in base currency</p></div><div className="flex items-center gap-2"><Dropdown value={changeCurrency} onChange={(v) => setChangeCurrency(v)} triggerClass="h-9 rounded-lg border border-[#d8e5cf] bg-white px-2 text-xs font-bold text-[#4f6746] dark:border-[#363740] dark:bg-[#1f2025] dark:text-[#9fd977]" options={currencyCodes.map((code) => ({ value: code, label: code }))} /><span className="text-sm font-extrabold text-[#4d7439]">{changeAmount === null ? "Rate required" : formatCurrencyAmount(changeAmount, changeCurrency)}</span></div></div></div>}{error && <p className="mt-4 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2.5 text-xs leading-5 text-[#c2564b]">{error}</p>}{hasUnknownRate && <p className="mt-3 rounded-lg bg-[#fff7e6] px-3 py-2 text-[10px] leading-5 text-[#9e7628]">Set an exchange rate in Settings before accepting this currency.</p>}<div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button><Button className="flex-[1.5]" disabled={loading || tenderedBase < total || hasUnknownRate || (changeBase > 0 && changeAmount === null)} onClick={() => onConfirm({ tenders, changeCurrency })}>{loading ? "Creating order..." : "Complete sale"} <Check size={15} /></Button></div></Modal>;}

function LivePOSView({ products, cart, setCart, notify, currencies, rates, baseCurrency, storeTaxRate = 10, storeTaxInclusive = false, storeTaxLabel = "Service tax", allowDiscounts = true, allowTip = true, chargeTax = true, saleSound = false, requireOpenShift = false, token, storeId, onCreateOrder, onOrderCompleted, orderLoading, orderError, pendingPayment, onCompleteMock, clearPendingPayment, heldOrders = [], heldLoading = false, heldError = "", onHold, onResumeHeld, onDiscardHeld, refreshHeldOrders }) {  const [category, setCategory] = useState("All items");
const [search, setSearch] = useState("");
const [checkoutOpen, setCheckoutOpen] = useState(false);
const [tenders, setTenders] = useState([{ method: "cash", currency_code: baseCurrency, amount: "" }]);
const [changeCurrency, setChangeCurrency] = useState(baseCurrency);
const [holdOpen, setHoldOpen] = useState(false);
const [heldOpen, setHeldOpen] = useState(false);
const [scanOpen, setScanOpen] = useState(false);
const [customer, setCustomer] = useState(null);
const [customerPickerOpen, setCustomerPickerOpen] = useState(false);
const [discountPct, setDiscountPct] = useState("");
const [discountMode, setDiscountMode] = useState("percent");
const [tipAmount, setTipAmount] = useState("");  const sellableProducts = products.filter((product) => product.is_active !== false);  const categories = ["All items", ...new Set(sellableProducts.map((product) => product.category).filter(Boolean))];  const filtered = sellableProducts.filter((product) => (category === "All items" || product.category === category) && `${product.name} ${product.sku}`.toLowerCase().includes(search.toLowerCase()));  const subtotal = cart.reduce((total, item) => total + item.price * item.quantity, 0);  const taxRate = Number(storeTaxRate) || 10;  const discountPctValue = Math.max(0, Math.min(100, Number(discountPct) || 0));  const discount = Number((subtotal * discountPctValue / 100).toFixed(2));  const inclusiveTotal = Number((subtotal - discount).toFixed(2));  const computedTax = storeTaxInclusive ? Number((inclusiveTotal * taxRate / (100 + taxRate)).toFixed(2)) : Number((inclusiveTotal * taxRate / 100).toFixed(2));  const tax = chargeTax ? computedTax : 0;  const total = chargeTax ? (storeTaxInclusive ? inclusiveTotal : Number((inclusiveTotal + computedTax).toFixed(2))) : inclusiveTotal;  const tipValue = allowTip ? (Number(tipAmount) || 0) : 0;  const chargeTotal = Number((total + tipValue).toFixed(2));  const addToCart = (product) => setCart((current) => { const existing = current.find((item) => item.id === product.id); if (existing) return current.map((item) => item.id === product.id ? { ...item, quantity: Math.min(item.quantity + 1, product.stock) } : item); return [...current, { ...product, quantity: 1 }]; });  const changeQuantity = (id, amount) => setCart((current) => current.flatMap((item) => item.id === id ? (item.quantity + amount > 0 ? [{ ...item, quantity: item.quantity + amount }] : []) : [item]));  const openCheckout = () => { if (requireOpenShift && !shift) { notify("Open a shift before taking payment (POS preference)"); return; } setTenders([{ method: "cash", currency_code: baseCurrency, amount: chargeTotal.toFixed(baseCurrency === "KHR" ? 0 : 2) }]); setChangeCurrency(baseCurrency); setCheckoutOpen(true); };const submitOrder = async ({ tenders: nextTenders, changeCurrency: nextChangeCurrency }) => { const order = await onCreateOrder({ items: cart.map((item) => ({ product_id: item.id, quantity: item.quantity })), tenders: nextTenders.map((tender) => ({ ...tender, amount: Number(tender.amount) })), change_currency_code: nextChangeCurrency, customer_id: customer?.id || undefined, discount: Number(discount.toFixed(2)), tip: Number(tipValue.toFixed(2)) }); if (order?.status === "paid") { playSaleSound(); setCart([]); setCustomer(null); setDiscountPct(""); setTipAmount(""); setCheckoutOpen(false); setTenders([{ method: "cash", currency_code: baseCurrency, amount: "" }]); onOrderCompleted?.(order); } return order; };const completeMock = async (payment) => { const order = await onCompleteMock(payment); if (order) { playSaleSound(); setCheckoutOpen(false); setCustomer(null); setDiscountPct(""); setTenders([{ method: "cash", currency_code: baseCurrency, amount: "" }]); onOrderCompleted?.(order); } return order; };const pending = pendingPayment || null;  const openHold = () => { if (cart.length === 0) { notify("Add items to your order before holding"); return; } setHoldOpen(true); };const openHeld = () => { setHeldOpen(true); refreshHeldOrders?.(); };const openScan = () => setScanOpen(true);  const playSaleSound = () => {    if (!saleSound) return;    try {      const AudioContext = window.AudioContext || window.webkitAudioContext;      if (!AudioContext) return;      const context = new AudioContext();      const oscillator = context.createOscillator();      const gain = context.createGain();      oscillator.frequency.value = 880;      oscillator.connect(gain);      gain.connect(context.destination);      gain.gain.setValueAtTime(0.001, context.currentTime);      gain.gain.exponentialRampToValueAtTime(0.18, context.currentTime + 0.02);      gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + 0.15);      oscillator.start();      oscillator.stop(context.currentTime + 0.16);    } catch { /* audio unavailable */ }  };const [shift, setShift] = useState(null);
const [shiftModal, setShiftModal] = useState(false);
const [shiftMode, setShiftMode] = useState("open");
const [floatValue, setFloatValue] = useState("50");
const [countedValue, setCountedValue] = useState("");
const [shiftNotes, setShiftNotes] = useState("");
const [shiftBusy, setShiftBusy] = useState(false);
const [closedShift, setClosedShift] = useState(null);
const [shiftHistory, setShiftHistory] = useState([]);
const [shiftHistoryOpen, setShiftHistoryOpen] = useState(false);  const openShiftHistory = async () => {    setShiftHistoryOpen(true);    try { setShiftHistory(await api.shifts(token, storeId)); } catch { /* ignore */ }  };const loadShift = async () => { try { setShift(await api.currentShift(token, storeId)); } catch { /* offline state ok */ } };  useEffect(() => { loadShift(); }, [token, storeId]);  const openShiftModal = () => { setShiftMode(shift ? "close" : "open"); setShiftModal(true); };const startShift = async () => {    setShiftBusy(true);    try {      const opened = await api.openShift(token, storeId, { opening_float: Number(floatValue) || 0 });      setShift(opened);      setShiftModal(false);      notify("Shift opened");    } catch (requestError) { notify(requestError.message || "Could not open shift"); } finally { setShiftBusy(false); }  };const endShift = async () => {    setShiftBusy(true);    try {      const closed = await api.closeShift(token, storeId, shift.id, { counted_cash: countedValue === "" ? null : Number(countedValue), notes: shiftNotes.trim() || null });      setClosedShift(closed);      setShift(null);      setShiftMode("done");    } catch (requestError) { notify(requestError.message || "Could not close shift"); } finally { setShiftBusy(false); }  };const cartItemCount = cart.reduce((count, item) => count + item.quantity, 0);  return <div className="flex h-[calc(100vh-74px)] min-h-[680px] flex-col xl:flex-row"><div className="app-scrollbar min-w-0 flex-1 overflow-y-auto p-5 lg:p-7"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><div className="flex items-center gap-2 text-xs text-[#92939d]"><span className="h-2 w-2 rounded-full bg-[#78bd4f]" /> Connected to Chmaba API</div><h2 className="mt-2 text-2xl font-extrabold tracking-[-.05em]">Make a sale</h2></div><div className="flex items-center gap-2"><Button variant="outline" size="sm" onClick={openShiftModal}>{shift ? <span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#78bd4f]" /> Shift {formatCurrencyAmount(Number(shift.opening_float), baseCurrency)}</span> : <span className="flex items-center gap-1.5"><Banknote size={14} /> Open shift</span>}</Button><Button variant="ghost" size="sm" onClick={openShiftHistory}><CalendarDays size={14} /> Shifts</Button><Button variant="outline" size="sm" onClick={openScan}><ScanLine size={14} /> Scan item</Button><Button variant="soft" size="sm" onClick={openHold} disabled={cart.length === 0}><Receipt size={14} /> Hold order</Button><Button variant="outline" size="sm" onClick={openHeld}><Archive size={14} /> Held{heldOrders.length > 0 && <span className="ml-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#17181c] px-1 text-[10px] font-extrabold text-white">{heldOrders.length}</span>}</Button></div></div><div className="relative mt-6"><Search size={16} className="absolute left-3.5 top-3 text-[#a1a2ab]" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search products by name or SKU..." className="h-11 w-full rounded-xl border border-[#e2e2e9] bg-white pl-10 pr-4 text-sm outline-none transition focus:border-[#887bf3] focus:ring-4 focus:ring-[#6957f5]/10" /></div><div className="mt-5 flex gap-2 overflow-x-auto pb-1">{categories.map((item) => <button key={item} onClick={() => setCategory(item)} className={`whitespace-nowrap rounded-lg px-3.5 py-2 text-xs font-bold transition ${category === item ? "bg-[#17181c] text-white" : "bg-white text-[#858690] hover:bg-[#efeff4]"}`}>{item}</button>)}</div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-4">{filtered.map((product) => <button key={product.id} onClick={() => addToCart(product)} disabled={product.stock === 0} className="group rounded-2xl border border-[#e8e8ee] bg-white p-3 text-left transition hover:-translate-y-0.5 hover:border-[#aaa1f5] hover:shadow-soft disabled:cursor-not-allowed disabled:opacity-50"><div className="relative"><div className="flex aspect-[1.25/1] items-center justify-center rounded-xl" style={{ backgroundColor: `${product.color}99` }}><span className="text-xl font-extrabold tracking-[-.08em] text-[#413a38]">{product.letter}</span></div>{product.stock <= 10 && <span className="absolute left-2 top-2 rounded-md bg-[#fff5dc] px-1.5 py-1 text-[9px] font-bold text-[#ae7e1e]">{product.stock} left</span>}<span className="absolute bottom-2 right-2 flex h-7 w-7 items-center justify-center rounded-lg bg-white/90 text-[#6957f5] opacity-0 shadow-sm transition group-hover:opacity-100"><Plus size={15} /></span></div><p className="mt-3 truncate text-xs font-extrabold text-[#303139]">{product.name}</p><div className="mt-1 flex items-center justify-between"><p className="text-[10px] text-[#92939d]">{product.category}</p><p className="text-xs font-extrabold text-[#303139]">{formatCurrencyAmount(product.price, baseCurrency)}</p></div></button>)}</div>{filtered.length === 0 && <div className="py-20 text-center text-sm text-[#92939d]">No products match your search.</div>}</div><aside className="flex w-full shrink-0 flex-col border-t border-[#e5e5eb] bg-white xl:w-[390px] xl:border-l xl:border-t-0"><div className="flex items-center justify-between border-b border-[#eeeeF2] px-5 py-4"><div><h3 className="text-sm font-extrabold">Current order</h3><p className="mt-1 text-[10px] text-[#999aa4]">Live order · {baseCurrency} base currency</p></div><button onClick={() => setCart([])} className="text-[10px] font-bold text-[#aaabb4] hover:text-[#c2564b]">Clear all</button></div><div className="app-scrollbar min-h-[170px] flex-1 overflow-y-auto px-5 py-4">{cart.length === 0 ? <div className="flex h-full min-h-[170px] flex-col items-center justify-center text-center"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#f3f2ff] text-[#8a7df0]"><ShoppingCart size={20} /></div><p className="mt-3 text-xs font-bold text-[#565762]">Your order is empty</p><p className="mt-1 text-[11px] text-[#a1a2ab]">Tap a product to add it here</p></div> : <div className="space-y-4">{cart.map((item) => <div key={item.id} className="flex gap-3"><ProductMark product={item} size="sm" /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><p className="truncate text-xs font-bold">{item.name}</p><p className="text-xs font-extrabold">{formatCurrencyAmount(item.price * item.quantity, baseCurrency)}</p></div><div className="mt-2 flex items-center justify-between"><p className="text-[10px] text-[#999aa4]">{formatCurrencyAmount(item.price, baseCurrency)} each</p><div className="flex items-center gap-2 rounded-lg bg-[#f3f3f6] p-0.5"><button onClick={() => changeQuantity(item.id, -1)} className="flex h-6 w-6 items-center justify-center rounded-md text-[#72737d] hover:bg-white"><Minus size={12} /></button><span className="w-4 text-center text-[10px] font-bold">{item.quantity}</span><button onClick={() => changeQuantity(item.id, 1)} className="flex h-6 w-6 items-center justify-center rounded-md bg-white text-[#6957f5] shadow-sm"><Plus size={12} /></button></div></div></div></div>)}</div>}</div><div className="border-t border-[#eeeeF2] px-5 py-3"><button onClick={() => setCustomerPickerOpen(true)} className="flex w-full items-center justify-between gap-3 rounded-lg px-1 py-1 text-left"><span className="text-[11px] font-semibold text-[#999aa4]">Customer</span>{customer ? <span className="flex min-w-0 items-center gap-2"><span className="truncate text-xs font-extrabold text-[#4d4e57]">{customer.name}</span>{customer.phone && <span className="hidden text-[10px] text-[#92939d] md:block">{customer.phone}</span>}<span onClick={(event) => { event.stopPropagation(); setCustomer(null); }} className="text-[#aaabb4] hover:text-[#c2564b]"><X size={13} /></span></span> : <span className="text-xs font-bold text-[#6957f5]">Guest <ChevronDown size={13} className="inline" /></span>}</button></div><div className="border-t border-[#eeeeF2] px-5 py-4"><div className="space-y-2 text-xs"><div className="flex justify-between text-[#858690]"><span>Subtotal</span><span className="font-semibold text-[#42434b]">{formatCurrencyAmount(subtotal, baseCurrency)}</span></div>{allowDiscounts && <div className="flex items-center justify-between gap-2 rounded-lg border border-[#e9e9ef] bg-[#fafafd] px-2.5 py-2"><span className="flex items-center gap-1.5 font-semibold text-[#4d4e57]"><Percent size={12} className="text-[#92939d]" /> Discount</span><Dropdown value={discountMode} onChange={(v) => setDiscountMode(v)} triggerClass="h-7 rounded-md border border-[#e1e1e8] bg-white px-1 text-[10px] font-bold text-[#292a31] dark:border-[#363740] dark:bg-[#1f2025] dark:text-[#e4e4e8]" options={[{ value: "percent", label: "%" }, { value: "amount", label: baseCurrency }]} /><span className="flex items-center gap-1.5"><input type="number" min="0" max="100" step="1" value={discountPct} onChange={(event) => setDiscountPct(event.target.value)} placeholder="0" className="h-7 w-14 rounded-md border border-[#e1e1e8] bg-white px-2 text-right text-[11px] font-bold outline-none focus:border-[#887bf3]" /><span className="text-[10px] text-[#92939d]">{discountMode === "amount" ? baseCurrency : "%"}</span>{discount > 0 && <span onClick={() => setDiscountPct("")} className="text-[#aaabb4] hover:text-[#c2564b]"><X size={12} /></span>}</span></div>}{allowDiscounts && discount > 0 && <div className="flex justify-between text-[#777883]"><span>Discount</span><span className="font-semibold text-[#66a53d]">-{formatCurrencyAmount(discount, baseCurrency)}</span></div>}{chargeTax && (<div className="flex justify-between text-[#858690]"><span>{storeTaxLabel} <span className="text-[10px]">({taxRate}%{storeTaxInclusive ? " incl." : ""})</span></span><span className="font-semibold text-[#42434b]">{formatCurrencyAmount(tax, baseCurrency)}</span></div>)}{allowTip && (<div className="flex items-center justify-between gap-2 text-[#777883]"><span>Tip</span><span className="flex items-center gap-1"><span className="text-[10px]">optional</span><input type="number" min="0" step="0.01" value={tipAmount} onChange={(event) => setTipAmount(event.target.value)} placeholder="0.00" className="h-7 w-16 rounded-md border border-[#e1e1e8] bg-white px-2 text-right text-[11px] font-bold outline-none focus:border-[#887bf3]" /></span></div>)}<div className="my-3 h-px border-t border-dashed border-[#dfe0e7]" /><div className="flex justify-between text-sm font-extrabold"><span>Total</span><span>{formatCurrencyAmount(total, baseCurrency)}</span></div></div><Button disabled={cart.length === 0 || pending} className="mt-4 w-full" size="lg" onClick={openCheckout}>{pending ? "Waiting for payment..." : `Charge ${formatCurrencyAmount(chargeTotal, baseCurrency)}`} <ArrowRight size={15} /></Button><p className="mt-3 flex items-center justify-center gap-1.5 text-[10px] text-[#a2a3ac]"><ShieldCheck size={12} /> Real stock check · API order</p></div></aside>{shiftModal && <Modal open onClose={() => setShiftModal(false)} title={shiftMode === "done" ? "Shift closed" : shiftMode === "close" ? "Close shift" : "Open shift"} description={shiftMode === "open" ? "Start your register with a starting float." : shiftMode === "close" ? "Count the drawer to close this shift." : "Summary for your cashier session."} width="max-w-[440px]">{shiftMode === "open" ? <><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Opening float</span><input type="number" min="0" step="0.01" value={floatValue} onChange={(event) => setFloatValue(event.target.value)} className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm outline-none focus:border-[#887bf3]" /></label><p className="mt-3 text-[11px] leading-5 text-[#92939d]">Sales made after opening are tracked for this register and cashier until you close the shift.</p><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={() => setShiftModal(false)}>Cancel</Button><Button className="flex-1" onClick={startShift} disabled={shiftBusy}>{shiftBusy ? "Opening..." : "Open shift"} <Check size={15} /></Button></div></> : shiftMode === "close" ? <><div className="rounded-xl bg-[#f7f7fa] p-4 text-xs"><div className="flex justify-between text-[#858690]"><span>Opening float</span><span className="font-bold text-[#4d4e57]">{formatCurrencyAmount(Number(shift?.opening_float), baseCurrency)}</span></div><p className="mt-2 text-[10px] text-[#92939d]">Expected drawer is computed from cash sales and cash refunds made on this shift.</p></div><label className="mt-4 block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Counted cash</span><input type="number" min="0" step="0.01" value={countedValue} onChange={(event) => setCountedValue(event.target.value)} className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm outline-none focus:border-[#887bf3]" placeholder="0.00" /></label><label className="mt-4 block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Notes (optional)</span><input value={shiftNotes} onChange={(event) => setShiftNotes(event.target.value)} placeholder="e.g. End of day" className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm outline-none focus:border-[#887bf3]" /></label><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={() => setShiftModal(false)}>Cancel</Button><Button className="flex-1" onClick={endShift} disabled={shiftBusy}>{shiftBusy ? "Closing..." : "Close shift"} <Check size={15} /></Button></div></> : closedShift ? <><div className="print-z-area space-y-2 rounded-xl bg-[#f7f7fa] p-4 text-xs">{[["Sales total", closedShift.sales_total], ["Cash received", closedShift.cash_received], ["Cash refunds", closedShift.cash_refunds], ["Expected drawer", closedShift.expected_cash], ["Counted", closedShift.counted_cash ?? "—"], ["Difference", closedShift.difference == null ? "—" : closedShift.difference]].map(([label, value]) => <div key={label} className="flex justify-between"><span className="text-[#858690]">{label}</span><span className={`font-extrabold ${String(label).toLowerCase().includes("difference") && Number(value) < 0 ? "text-[#c2564b]" : "text-[#4d4e57]"}`}>{typeof value === "number" ? formatCurrencyAmount(value, baseCurrency) : value}</span></div>)}<div className="flex justify-between border-t border-[#e3e3ea] pt-2"><span className="text-[#858690]">Orders</span><span className="font-extrabold text-[#4d4e57]">{closedShift.orders_count}</span></div></div><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={() => window.print()}><Download size={14} /> Print Z report</Button><Button className="flex-1" onClick={() => setShiftModal(false)}>Done</Button></div></> : null}</Modal>}{shiftHistoryOpen && <Modal open onClose={() => setShiftHistoryOpen(false)} title="Shift history" description="Past register sessions at this store." width="max-w-[720px]">{shiftHistory.length === 0 ? <p className="py-12 text-center text-xs text-[#92939d]">No shifts recorded yet.</p> : <div className="app-scrollbar max-h-[500px] space-y-2 overflow-y-auto">{shiftHistory.map((session) => <div key={session.id} className="rounded-xl border border-[#e9e9ef] p-3.5"><div className="flex flex-wrap items-center gap-3"><Badge tone={session.status === "open" ? "green" : "neutral"} dot>{session.status}</Badge><p className="text-xs font-extrabold">{session.cashier_name || "Staff"}</p><p className="text-[10px] text-[#999aa4]">{new Date(session.opened_at).toLocaleString()}{session.closed_at ? ` â†’ ${new Date(session.closed_at).toLocaleTimeString()}` : ""}</p></div><div className="mt-3 grid gap-2 text-[11px] sm:grid-cols-5"><div><p className="text-[10px] text-[#a1a2ab]">Sales</p><p className="mt-0.5 font-extrabold">{formatCurrencyAmount(Number(session.sales_total), baseCurrency)}</p></div><div><p className="text-[10px] text-[#a1a2ab]">Expected</p><p className="mt-0.5 font-extrabold">{formatCurrencyAmount(Number(session.expected_cash), baseCurrency)}</p></div><div><p className="text-[10px] text-[#a1a2ab]">Counted</p><p className="mt-0.5 font-extrabold">{session.counted_cash == null ? "—" : formatCurrencyAmount(Number(session.counted_cash), baseCurrency)}</p></div><div><p className="text-[10px] text-[#a1a2ab]">Difference</p><p className={`mt-0.5 font-extrabold ${Number(session.difference) < 0 ? "text-[#c2564b]" : Number(session.difference) > 0 ? "text-[#66a53d]" : "text-[#4d4e57]"}`}>{session.difference == null ? "—" : formatCurrencyAmount(Number(session.difference), baseCurrency)}</p></div><div><p className="text-[10px] text-[#a1a2ab]">Orders</p><p className="mt-0.5 font-extrabold">{session.orders_count}</p></div></div></div>)}</div>}<div className="mt-5 flex justify-end"><Button variant="outline" onClick={() => setShiftHistoryOpen(false)}>Close</Button></div></Modal>}{scanOpen && <ScanModal open onClose={() => setScanOpen(false)} products={sellableProducts} onAdd={addToCart} />}{customerPickerOpen && <CustomerPickerModal open onClose={() => setCustomerPickerOpen(false)} token={token} notify={notify} onPick={(picked) => { setCustomer(picked); setCustomerPickerOpen(false); }} />}<HoldCartModal open={holdOpen} onClose={() => setHoldOpen(false)} itemCount={cartItemCount} total={total} baseCurrency={baseCurrency} busy={orderLoading} error={heldError} onConfirm={onHold} /><HeldOrdersModal open={heldOpen} onClose={() => setHeldOpen(false)} heldOrders={heldOrders} loading={heldLoading} busy={orderLoading} cartItemCount={cartItemCount} baseCurrency={baseCurrency} onResume={onResumeHeld} onDiscard={onDiscardHeld} /><POSPaymentModal open={checkoutOpen || Boolean(pending)} onClose={() => { setCheckoutOpen(false); clearPendingPayment?.(); }} total={total} baseCurrency={baseCurrency} currencies={currencies} rates={rates} tenders={tenders} setTenders={setTenders} changeCurrency={changeCurrency} setChangeCurrency={setChangeCurrency} onConfirm={submitOrder} loading={orderLoading} error={orderError} pendingPayment={pending} onCompleteMock={completeMock} /></div>;}

function ScanModal({ open, onClose, products, onAdd }) {  const [query, setQuery] = useState("");
const [error, setError] = useState("");
const [delta, setDelta] = useState("10");  const adjustPoints = async (value) => { try { const res = await api.adjustCustomerPoints(token, customerId, value); setDetail((current) => current ? { ...current, customer: { ...current.customer, points: res.points } } : current); } catch (requestError) { setError(requestError.message || "Could not adjust points"); } };const [added, setAdded] = useState([]);  const scan = () => {    const value = query.trim().toLowerCase();    if (!value) return;    const match = products.find((product) => String(product.sku).toLowerCase() === value || product.name.toLowerCase() === value);    if (!match) { setError(`No product matches "${query.trim()}"`); return; }    if (match.stock <= 0) { setError(`${match.name} is out of stock`); return; }    setError("");    onAdd(match);    setAdded((current) => { const existing = current.find((item) => item.id === match.id); return existing ? current.map((item) => item.id === match.id ? { ...item, count: item.count + 1 } : item) : [...current, { id: match.id, name: match.name, count: 1 }]; });    setQuery("");  };const handleKey = (event) => { if (event.key === "Enter") { event.preventDefault(); scan(); } };  return <Modal open={open} onClose={onClose} title="Scan an item" description="Point a barcode scanner here or type a SKU. Scanned items are added straight to the cart." width="max-w-[460px]"><div className="flex gap-2"><input autoFocus value={query} onChange={(event) => { setQuery(event.target.value); setError(""); }} onKeyDown={handleKey} placeholder="Barcode or SKU (e.g. FLOW-A2F7DD76)" className="h-12 min-w-0 flex-1 rounded-xl border border-[#dfe0e8] bg-white px-4 text-sm tracking-wide text-[#22232a] outline-none placeholder:text-[#aaabb4] focus:border-[#887bf3]" /><Button onClick={scan} disabled={!query.trim()}><Plus size={16} /> Add</Button></div>{error && <p className="mt-3 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2 text-xs text-[#c2564b]">{error}</p>}{added.length > 0 && <div className="mt-4 rounded-xl border border-[#e9e9ef] bg-[#fafafd] p-4"><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#a1a2ab]">Added this session</p><div className="mt-3 space-y-2">{added.map((item) => <div key={item.id} className="flex items-center justify-between text-xs"><span className="font-bold">{item.name}</span><span className="font-extrabold text-[#6957f5]">x {item.count}</span></div>)}</div></div>}<div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Done</Button></div></Modal>;}

function HoldCartModal({ open, onClose, itemCount, total, baseCurrency = "USD", busy = false, error = "", onConfirm }) {  const [label, setLabel] = useState("");  const submit = async () => { const result = await onConfirm(label.trim()); if (result) onClose(); };  return <Modal open={open} onClose={onClose} title="Hold this order" description="Park it on the register so it can be finished later." width="max-w-[460px]"><div className="rounded-xl border border-[#e9e9ef] bg-[#fafafd] p-4"><div className="flex items-center justify-between gap-3 text-xs"><span className="text-[#858690]">{itemCount} item{itemCount === 1 ? "" : "s"} in this order</span><span className="text-base font-extrabold">{formatCurrencyAmount(total, baseCurrency)}</span></div><p className="mt-2 text-[10px] leading-4 text-[#a1a2ab]">Held orders stay on this store's register. Stock is not reserved and prices refresh when you resume.</p></div><div className="mt-4"><label className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Label (optional)</label><input value={label} onChange={(event) => setLabel(event.target.value)} placeholder="e.g. Table 4 · Pisey waiting" className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm text-[#22232a] outline-none placeholder:text-[#aaabb4] focus:border-[#887bf3]" autoFocus /></div>{error && <p className="mt-3 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2 text-xs text-[#c2564b]">{error}</p>}<div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button><Button className="flex-1" disabled={busy || itemCount === 0} onClick={submit}>{busy ? "Holding..." : "Hold order"} <Archive size={15} /></Button></div></Modal>;}

function HeldOrdersModal({ open, onClose, heldOrders, loading = false, busy = false, cartItemCount = 0, baseCurrency = "USD", onResume, onDiscard }) {  const [confirm, setConfirm] = useState(null);  const closeAll = () => { setConfirm(null); onClose(); };const beginResume = (held) => { if (cartItemCount > 0) setConfirm({ action: "resume", held }); else runResume(held); };const runResume = async (held) => { const ok = await onResume(held); if (ok) closeAll(); };const runDiscard = async (held) => { const ok = await onDiscard(held); if (ok) setConfirm(null); };  return <Modal open={open} onClose={closeAll} title="Held orders" description="Orders parked at this store, ready to resume." width="max-w-[540px]">{loading && heldOrders.length === 0 ? <div className="py-12 text-center text-xs text-[#92939d]">Loading held orders...</div> : heldOrders.length === 0 ? <div className="py-12 text-center"><div className="mx-auto flex h-11 w-11 items-center justify-center rounded-2xl bg-[#f3f2ff] text-[#8a7df0]"><Archive size={18} /></div><p className="mt-3 text-xs font-bold text-[#565762]">Nothing held right now</p><p className="mt-1 text-[11px] text-[#a1a2ab]">Hold an order to park it here and resume it later.</p></div> : <div className="space-y-2">{heldOrders.map((held) => { const isConfirming = confirm?.held.id === held.id; return <div key={held.id} className="rounded-xl border border-[#e7e7ed] bg-white p-3"><div className="flex items-start gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f3f2ff] text-[#8a7df0]"><Receipt size={15} /></div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-3"><p className="truncate text-xs font-extrabold">{held.label || "Held order"}</p><p className="shrink-0 text-xs font-extrabold">{formatCurrencyAmount(Number(held.total), baseCurrency)}</p></div><p className="mt-1 text-[10px] text-[#999aa4]">{held.item_count} item(s) · held by {held.cashier_name || "staff"} · {new Date(held.created_at).toLocaleString()}</p></div></div>{isConfirming ? <div className="mt-3 rounded-xl border border-[#eadcd8] bg-[#fdf7f5] p-3"><p className="text-[11px] font-semibold text-[#8f5a52]">{confirm.action === "resume" ? "Resuming replaces the order currently in your cart." : "This permanently discards this held order."}</p><div className="mt-2.5 flex gap-2"><Button variant="outline" size="sm" onClick={() => setConfirm(null)}>Keep</Button>{confirm.action === "resume" ? <Button size="sm" disabled={busy} onClick={() => runResume(held)}>{busy ? "Resuming..." : "Resume anyway"} <ArrowRight size={13} /></Button> : <Button variant="danger" size="sm" disabled={busy} onClick={() => runDiscard(held)}>{busy ? "Discarding..." : "Discard"} <Trash2 size={13} /></Button>}</div></div> : <div className="mt-3 flex gap-2"><Button variant="soft" size="xs" className="flex-1" disabled={busy} onClick={() => beginResume(held)}>Resume <ArrowRight size={13} /></Button><Button variant="ghost" size="xs" className="text-[#a0695f]" onClick={() => setConfirm({ action: "discard", held })}>Discard <Trash2 size={13} /></Button></div>}</div>; })}</div>}</Modal>;}

function PaymentModal({ open, onClose, total, method, setMethod, onConfirm, plan = false, planName = "Starter" }) {  const methods = [{ id: "cash", label: "Cash", icon: Banknote }, { id: "card", label: "Card", icon: CreditCard }, { id: "khqr", label: "KHQR", icon: QrCode }];  return <Modal open={open} onClose={onClose} title={plan ? "Complete your upgrade" : "Complete payment"} description={plan ? "Scan with any Cambodian banking app." : "Choose payment method for this order."} width="max-w-[460px]"><div className="rounded-xl bg-[#f7f7fa] p-4"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-[#858690]">{plan ? `${planName} plan · Monthly` : "Amount due"}</span><span className="text-xl font-extrabold tracking-[-.04em]">{typeof total === "string" ? total : money(total)}</span></div></div><div className="mt-5 grid grid-cols-3 gap-2">{methods.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setMethod(id)} className={`flex flex-col items-center gap-2 rounded-xl border p-3 text-xs font-bold transition ${method === id ? "border-[#6957f5] bg-[#f5f3ff] text-[#6957f5] ring-2 ring-[#6957f5]/10" : "border-[#e6e6ed] text-[#777883] hover:border-[#beb9ef]"}`}><Icon size={18} />{label}</button>)}</div>{method === "khqr" ? <div className="mt-5 rounded-2xl border border-[#dfe8d7] bg-[#f8fcf5] p-5 text-center"><div className="mx-auto flex h-[148px] w-[148px] items-center justify-center rounded-xl border-[7px] border-white bg-white p-2 shadow-sm"><div className="qr-pattern h-full w-full rounded-sm" /></div><div className="mt-4 flex items-center justify-center gap-2"><span className="flex h-5 w-5 items-center justify-center rounded bg-[#ed2939] text-[8px] font-extrabold text-white">KH</span><span className="text-xs font-extrabold text-[#465142]">KHQR</span></div><p className="mt-1 text-[10px] text-[#84907e]">Scan to pay securely</p><p className="mt-3 text-[10px] font-semibold text-[#6c7966]">Expires in 14:52</p><p className="mt-4 text-[9px] font-semibold text-[#99a293]">Powered by <span className="text-[#5b6557]">cutluy.com</span></p></div> : <div className="mt-5 rounded-xl border border-[#e9e9ef] bg-white p-4"><p className="text-xs font-bold">{method === "cash" ? "Cash received" : "Card terminal"}</p><div className="mt-3 flex h-11 items-center rounded-lg bg-[#f7f7fa] px-3 text-sm font-bold text-[#36373f]">{method === "cash" ? "$0.00" : "Ready for tap or insert"}</div>{method === "cash" && <p className="mt-2 text-[10px] text-[#a0a1aa]">Enter amount received after confirming the order.</p>}</div>}<div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button><Button className="flex-[1.5]" onClick={onConfirm}>{method === "khqr" ? "Confirm payment" : "Complete sale"} <Check size={15} /></Button></div></Modal>;}

function LiveOrdersWithReceipt({ orders, workspace, loading, error, onRefresh, onOpenOrder, onRefundOrder, onCancelOrder, onLoadMore, memberRole = "owner", hasMore = false, loadingMore = false }) {  const canManage = ["owner", "manager", "inventory_manager"].includes(memberRole);
const [filter, setFilter] = useState("all");
const [cancelTarget, setCancelTarget] = useState(null);  const filtered = filter === "all" ? orders : orders.filter((order) => order.status === filter);  const currency = workspace?.store?.currency_code || "USD";  const statusTone = { paid: "green", payment_pending: "yellow", payment_expired: "red", payment_failed: "red", cancelled: "neutral", refunded: "violet" };  return <div className="mx-auto max-w-[1460px] p-5 lg:p-8"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-extrabold tracking-[-.05em]">Orders</h2><p className="mt-1 text-sm text-[#898a95]">Every order from {workspace?.store?.name}.</p></div><Button variant="outline" onClick={onRefresh} disabled={loading}><RefreshCw size={15} /> Refresh orders</Button></div>{error && <p className="mt-5 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2.5 text-xs text-[#c2564b]">{error}</p>}<div className="mt-7 grid gap-3 sm:grid-cols-3"><SmallStat label="Orders loaded" value={orders.length} detail="Latest orders" icon={Receipt} tone="violet" /><SmallStat label="Paid orders" value={orders.filter((order) => order.status === "paid").length} detail="Completed sales" icon={CheckCircle2} tone="green" /><SmallStat label="Pending payment" value={orders.filter((order) => order.status === "payment_pending").length} detail="Awaiting KHQR" icon={Clock3} tone="yellow" /></div><div className="mt-5 rounded-2xl border border-[#e9e9ef] bg-white p-4 sm:p-6"><div className="flex items-center gap-1 overflow-x-auto rounded-xl bg-[#f6f6f9] p-1">{[{ value: "all", label: "All orders" }, { value: "paid", label: "Paid" }, { value: "payment_pending", label: "Pending" }, { value: "cancelled", label: "Cancelled" }].map((item) => <button key={item.value} onClick={() => setFilter(item.value)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-[11px] font-bold ${filter === item.value ? "bg-white text-[#4d4e57] shadow-sm" : "text-[#92939d]"}`}>{item.label}</button>)}</div><div className="app-scrollbar mt-5 overflow-x-auto"><table className="mobile-table w-full border-collapse text-left"><thead><tr className="border-y border-[#f0f0f3] text-[10px] font-bold uppercase tracking-wide text-[#a1a2ab]"><th className="py-3 pl-2 font-bold">Order</th><th className="px-4 py-3 font-bold">Customer</th><th className="px-4 py-3 font-bold">Items</th><th className="px-4 py-3 font-bold">Payment</th><th className="px-4 py-3 font-bold">Status</th><th className="px-4 py-3 text-right font-bold">Total</th><th className="w-28 px-2 py-3 text-right font-bold">Actions</th></tr></thead><tbody>{filtered.map((order) => <tr key={order.id} className="border-b border-[#f2f2f5] last:border-0"><td className="py-3.5 pl-2"><p className="text-xs font-extrabold">{order.order_number}</p><p className="mt-0.5 text-[10px] text-[#a1a2ab]">{new Date(order.created_at).toLocaleString()}</p></td><td className="px-4 py-3.5 text-xs text-[#656670]">{order.customer?.name || order.customer_name || "Walk-in customer"}</td><td className="px-4 py-3.5 text-xs text-[#777883]">{order.items.length} item(s)</td><td className="px-4 py-3.5 text-xs font-semibold capitalize text-[#777883]">{order.payments[0]?.provider || order.tenders[0]?.method || "-"}</td><td className="px-4 py-3.5"><Badge tone={statusTone[order.status] || "neutral"} dot>{order.status === "paid" && Number(order.refunded_amount) > 0 ? "Partially refunded" : order.status.replaceAll("_", " ")}</Badge></td><td className="px-4 py-3.5 text-right text-xs font-extrabold">{formatCurrencyAmount(Number(order.total), currency)}</td><td className="px-2 py-3.5"><div className="flex items-center justify-end gap-1"><IconButton label="View receipt" onClick={() => onOpenOrder(order)}><Eye size={15} /></IconButton>{canManage && order.status === "paid" && Number(order.refunded_amount) < Number(order.total) && <IconButton label="Refund order" onClick={() => onRefundOrder?.(order)}><RotateCcw size={15} /></IconButton>}{canManage && order.status === "payment_pending" && <IconButton label="Cancel order" onClick={() => setCancelTarget(order)}><X size={15} /></IconButton>}</div></td></tr>)}</tbody></table></div>{filtered.length === 0 && <div className="py-16 text-center text-sm text-[#92939d]">No orders in this view.</div>}{filtered.length > 0 && hasMore && <div className="mt-5 flex justify-center"><Button variant="outline" size="sm" onClick={onLoadMore} disabled={loadingMore}>{loadingMore ? "Loading..." : "Load more orders"} <ChevronDown size={14} /></Button></div>}</div>{cancelTarget && <ConfirmDialog open title={`Cancel ${cancelTarget.order_number}?`} message="This voids the pending order so it cannot be paid. Held stock is released." confirmLabel="Cancel order" onConfirm={() => { onCancelOrder?.(cancelTarget.id); setCancelTarget(null); }} onCancel={() => setCancelTarget(null)} />}</div>;}

function CustomerPickerModal({ open, onClose, token, notify, onPick }) {  const [query, setQuery] = useState("");
const [rows, setRows] = useState([]);
const [loading, setLoading] = useState(false);
const [error, setError] = useState("");  const load = async (term) => { setLoading(true); setError(""); try { const params = {}; if (term.trim()) params.search = term.trim(); setRows(await api.customers(token, params)); } catch (requestError) { setError(requestError.message || "Could not load customers"); } finally { setLoading(false); } };  useEffect(() => { const handle = window.setTimeout(() => { load(query); }, query.trim() ? 250 : 0); return () => window.clearTimeout(handle); }, [query, token]);  const createNew = async () => { setError(""); try { const created = await api.createCustomer(token, { name: query.trim(), phone: null }); notify(`${created.name} added as a customer`); onPick(created); } catch (requestError) { setError(requestError.message || "Could not add customer"); } };const exactMatch = rows.some((row) => row.name.trim().toLowerCase() === query.trim().toLowerCase());  return <Modal open={open} onClose={onClose} title="Customer" description="Find a returning customer or add a new one." width="max-w-[480px]"><input value={query} onChange={(event) => setQuery(event.target.value)} autoFocus placeholder="Search by name or phone..." className="h-11 w-full rounded-xl border border-[#dfe0e8] bg-white px-4 text-sm outline-none focus:border-[#887bf3]" />{error && <p className="mt-3 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2 text-xs text-[#c2564b]">{error}</p>}<div className="app-scrollbar mt-3 max-h-[320px] space-y-1.5 overflow-y-auto">{loading && <p className="py-6 text-center text-xs text-[#92939d]">Searching...</p>}{!loading && rows.length === 0 && <p className="py-8 text-center text-xs text-[#92939d]">No customers found.</p>}{rows.map((row) => <button key={row.id} onClick={() => onPick(row)} className="flex w-full items-center gap-3 rounded-xl border border-[#e7e7ed] bg-white p-3 text-left transition hover:border-[#c9c3f2] hover:bg-[#fafaff]"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#ded9fb] text-[10px] font-extrabold text-[#5144c7]">{row.name.slice(0, 2).toUpperCase()}</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-extrabold text-[#34353d]">{row.name}</span><span className="mt-0.5 block truncate text-[10px] text-[#999aa4]">{row.phone || row.email || "No contact info"}</span></span></button>)}</div>{query.trim() && !loading && !exactMatch && <Button variant="soft" className="mt-3 w-full" onClick={createNew}><UserPlus size={15} /> Add "{query.trim()}" as a new customer</Button>}<div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button><Button variant="ghost" className="flex-1" onClick={() => { onClose(); onPick(null); }}>No customer (Guest)</Button></div></Modal>;}

function CustomerFormModal({ open, editing, token, onClose, onSaved, notify }) {  const [form, setForm] = useState({ name: "", phone: "", email: "", notes: "" });
const [busy, setBusy] = useState(false);
const [error, setError] = useState("");  useEffect(() => { setForm({ name: editing?.name || "", phone: editing?.phone || "", email: editing?.email || "", notes: editing?.notes || "" }); setError(""); }, [editing, open]);  const submit = async () => { setBusy(true); setError(""); try { const body = { name: form.name.trim(), phone: form.phone.trim() || null, email: form.email.trim() || null, notes: form.notes.trim() || null };const saved = editing ? await api.updateCustomer(token, editing.id, body) : await api.createCustomer(token, body); notify(`${saved.name} ${editing ? "updated" : "added"}`); onSaved(saved); } catch (requestError) { setError(requestError.message || "Could not save customer"); } finally { setBusy(false); } };  return <Modal open={open} onClose={onClose} title={editing ? `Edit ${editing.name}` : "Add a customer"} description="Customer records are shared across your stores." width="max-w-[480px]"><form onSubmit={(event) => { event.preventDefault(); submit(); }} className="space-y-4"><Field label="Name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="e.g. Sokha Lim" /><div className="grid gap-4 sm:grid-cols-2"><Field label="Phone" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} placeholder="+855 ..." /><Field label="Email" type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} placeholder="name@example.com" /></div><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Notes</span><textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} rows={3} className="w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 py-2.5 text-sm outline-none focus:border-[#887bf3]" /></label>{error && <p className="rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2 text-xs text-[#c2564b]">{error}</p>}<div className="flex gap-2 pt-1"><Button variant="outline" className="flex-1" type="button" onClick={onClose}>Cancel</Button><Button className="flex-1" type="submit" disabled={busy || !form.name.trim()}>{busy ? "Saving..." : editing ? "Save changes" : "Add customer"} <Check size={15} /></Button></div></form></Modal>;}

function CustomerDetailModal({ customerId, token, baseCurrency = "USD", onClose, onOpenOrder, onEdit }) {  const [detail, setDetail] = useState(null);
const [error, setError] = useState("");
const [delta, setDelta] = useState("10");  useEffect(() => { let active = true; (async () => { setError(""); try { const result = await api.customerDetail(token, customerId); if (active) setDetail(result); } catch (requestError) { if (active) setError(requestError.message || "Could not load customer"); } })(); return () => { active = false; }; }, [customerId, token]);  const adjustPoints = async (value) => { try { const res = await api.adjustCustomerPoints(token, customerId, value); setDetail((current) => current ? { ...current, customer: { ...current.customer, points: res.points } } : current); } catch (requestError) { setError(requestError.message || "Could not adjust points"); } };const customer = detail?.customer;  const tone = { paid: "green", payment_pending: "yellow", cancelled: "neutral", refunded: "violet" };  return <Modal open onClose={onClose} title="Customer profile" description={customer ? `${customer.name} · since ${new Date(customer.created_at).toLocaleDateString()}` : "Loading..."} width="max-w-[640px]">{error && <p className="mb-4 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2 text-xs text-[#c2564b]">{error}</p>}{!detail ? <div className="py-12 text-center text-xs text-[#92939d]">Loading customer history...</div> : <div><div className="grid gap-3 sm:grid-cols-3">{[{ label: "Orders", value: detail.orders_count }, { label: "Total spent", value: formatCurrencyAmount(Number(detail.total_spent), baseCurrency) }, { label: "Loyalty points", value: Math.floor(Number(customer?.points) || 0) }].map((stat, index) => <div key={index} className="rounded-xl border border-[#e9e9ef] bg-[#fafafd] p-4"><p className="text-[10px] font-semibold text-[#92939d]">{stat.label}</p><p className="mt-1 text-xl font-extrabold tracking-[-.04em]">{stat.value}</p></div>)}</div><div className="mt-4 rounded-xl border border-[#e9e9ef] p-4"><div className="flex items-center justify-between"><span className="text-xs font-extrabold">Adjust points</span></div><div className="mt-3 flex flex-wrap items-center gap-2"><input type="number" value={delta} onChange={(event) => setDelta(event.target.value)} className="h-9 w-24 rounded-lg border border-[#e1e1e8] bg-white px-2 text-xs outline-none" /><Button size="xs" onClick={() => adjustPoints(Number(delta) || 0)}><Plus size={13} /> Add</Button><Button variant="outline" size="xs" onClick={() => adjustPoints(-1 * (Number(delta) || 0))}><Minus size={13} /> Remove</Button></div></div><div className="mt-5 flex items-center justify-between"><h3 className="text-sm font-extrabold">Order history</h3><Button variant="outline" size="xs" onClick={() => { onClose(); onEdit?.(customer); }}><Edit3 size={13} /> Edit customer</Button></div><div className="mt-3 rounded-xl border border-[#eeeeF2]"><div className="app-scrollbar max-h-[360px] overflow-y-auto">{detail.orders.length === 0 ? <p className="py-10 text-center text-xs text-[#92939d]">No orders yet.</p> : detail.orders.map((order) => <div key={order.id} className="flex items-center gap-3 border-b border-[#f0f0f3] px-4 py-3 last:border-0"><div className="min-w-0 flex-1"><p className="text-xs font-extrabold">{order.order_number}</p><p className="mt-0.5 text-[10px] text-[#999aa4]">{new Date(order.created_at).toLocaleString()}</p></div><Badge tone={tone[order.status] || "neutral"}>{order.status.replaceAll("_", " ")}</Badge><p className="w-20 text-right text-xs font-extrabold">{formatCurrencyAmount(Number(order.total), baseCurrency)}</p><Button variant="soft" size="xs" onClick={() => onOpenOrder?.(order)}><Eye size={13} /> View</Button></div>)}</div></div><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Close</Button></div></div>}</Modal>;}

function LoyaltySettingsModal({ workspace, onUpdateStore, notify, loading, onClose }) {  const prefs = workspace?.store?.preferences || {};const [enabled, setEnabled] = useState(prefs.loyalty_enabled !== false);
const [rate, setRate] = useState(String(prefs.loyalty_pts_per_usd ?? 1));  const save = async () => { const updated = await onUpdateStore({ preferences: { ...prefs, loyalty_enabled: enabled, loyalty_pts_per_usd: Number(rate) || 0 } }); if (updated) { notify("Loyalty settings saved"); onClose(); } };  return <Modal open onClose={onClose} title="Loyalty & rewards" description="How points are earned and redeemed at this store." width="max-w-[480px]"><div className="space-y-4"><label className="flex items-center gap-3 rounded-xl border border-[#e9e9ef] px-4 py-3"><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} className="h-4 w-4 accent-[#6957f5]" /><span className="text-xs font-semibold text-[#4f5059]">Enable loyalty points <span className="block text-[10px] font-normal text-[#92939d]">Award points on paid orders for attached customers.</span></span></label><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Points per {workspace?.store?.currency_code || "USD"} spent</span><input type="number" min="0" step="1" value={rate} onChange={(event) => setRate(event.target.value)} className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm outline-none" disabled={!enabled} /></label></div><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button><Button className="flex-1" onClick={save} disabled={loading}>{loading ? "Saving..." : "Save settings"} <Check size={14} /></Button></div></Modal>;}

function LiveCustomersView({ token, workspace, notify, onOpenOrder, onUpdateStore }) {  const [rows, setRows] = useState([]);
const [query, setQuery] = useState("");
const [error, setError] = useState("");
const [form, setForm] = useState(null);
const [formEditing, setFormEditing] = useState(null);
const [detailCustomer, setDetailCustomer] = useState(null);
const [detail, setDetail] = useState(null);
const [toggleTarget, setToggleTarget] = useState(null);
const [deleteTarget, setDeleteTarget] = useState(null);  const baseCurrency = workspace?.store?.currency_code || "USD";  const load = async (term) => { try { const params = {}; if ((term ?? query).trim()) params.search = (term ?? query).trim(); setRows(await api.customers(token, params)); setError(""); } catch (requestError) { setError(requestError.message || "Could not load customers"); } };  useEffect(() => { load(""); }, [token]);  const debounceLoad = () => { const h = window.setTimeout(() => load(), 300); return () => window.clearTimeout(h); };  useEffect(debounceLoad, [query]);  const openDetail = async (customer) => { setDetailCustomer(customer); setDetail(null); try { setDetail(await api.customerDetail(token, customer.id)); } catch (requestError) { setError(requestError.message || "Could not load customer"); } };const adjustPoints = async (value) => { try { const res = await api.adjustCustomerPoints(token, detailCustomer.id, value); setDetail((current) => current ? { ...current, customer: { ...current.customer, points: res.points } } : current); } catch (requestError) { setError(requestError.message || "Could not adjust points"); } };const performToggle = async () => { const item = toggleTarget; if (!item) return; setToggleTarget(null); try { const updated = await api.updateCustomer(token, item.id, { is_active: item.activate }); setRows((current) => current.map((row) => row.id === updated.id ? updated : row)); notify(item.activate ? `${updated.name} activated` : `${updated.name} deactivated`); } catch (requestError) { notify(requestError.message || "Could not update customer"); } };const performDelete = async () => { const target = deleteTarget; setDeleteTarget(null); try { await api.deleteCustomer(token, target.id); notify("Customer deleted"); setRows((current) => current.filter((row) => row.id !== target.id)); } catch (requestError) { notify(requestError.message || "Could not delete customer"); } };const saveCustomer = async () => { try { const body = { name: form.name.trim(), phone: form.phone.trim() || null, email: form.email.trim() || null, notes: form.notes.trim() || null };const saved = formEditing ? await api.updateCustomer(token, formEditing.id, body) : await api.createCustomer(token, body); notify(formEditing ? `${saved.name} updated` : `${saved.name} added`); setForm(null); setFormEditing(null); await load(); } catch (requestError) { setError(requestError.message || "Could not save customer"); } };  return <div className="mx-auto max-w-[1460px] p-5 lg:p-8"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-extrabold tracking-[-.05em]">Customers</h2><p className="mt-1 text-sm text-[#898a95]">People who buy from {workspace?.store?.name}. Shared across all your stores.</p></div><Button onClick={() => { setFormEditing(null); setForm({ name: "", phone: "", email: "", notes: "" }); }}><UserPlus size={15} /> Add customer</Button></div>{error && <p className="mt-5 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2.5 text-xs text-[#c2564b]">{error}</p>}<div className="mt-7 grid gap-3 sm:grid-cols-3"><SmallStat label="Customers" value={rows.length} detail={query.trim() ? "Filtered results" : "Company-wide records"} icon={Users} tone="violet" /><SmallStat label="Active" value={rows.filter((item) => item.is_active !== false).length} detail="Attachable to sales" icon={ShieldCheck} tone="green" /><SmallStat label="With phone" value={rows.filter((item) => item.phone).length} detail="Reachable by phone" icon={Smartphone} tone="yellow" /></div><div className="mt-5 rounded-2xl border border-[#e9e9ef] bg-white p-4 sm:p-6"><div className="relative max-w-[380px]"><Search size={15} className="absolute left-3.5 top-3 text-[#a1a2ab]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search customers by name, phone or email..." className="h-10 w-full rounded-xl border border-[#e3e3ea] bg-[#fcfcfd] pl-10 pr-3 text-xs outline-none focus:border-[#887bf3]" /></div><div className="app-scrollbar mt-5 overflow-x-auto"><table className="mobile-table w-full border-collapse text-left"><thead><tr className="border-y border-[#f0f0f3] text-[10px] font-bold uppercase tracking-wide text-[#a1a2ab]"><th className="py-3 pl-2 font-bold">Customer</th><th className="px-4 py-3 font-bold">Phone</th><th className="px-4 py-3 font-bold">Email</th><th className="px-4 py-3 font-bold">Points</th><th className="px-4 py-3 font-bold">Status</th><th className="w-36 px-2 py-3 text-right font-bold">Actions</th></tr></thead><tbody>{rows.length === 0 ? <tr><td colSpan="6" className="py-14 text-center text-sm text-[#92939d]">No customers found.</td></tr> : rows.map((customer, index) => <tr key={customer.id} className="border-b border-[#f2f2f5] last:border-0"><td className="py-3.5 pl-2"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-full text-[10px] font-extrabold text-white" style={{ backgroundColor: PRODUCT_COLORS[index % PRODUCT_COLORS.length] }}>{customer.name.slice(0, 2).toUpperCase()}</div><p className="text-xs font-extrabold text-[#34353d]">{customer.name}</p></div></td><td className="px-4 py-3.5 text-xs text-[#777883]">{customer.phone || "-"}</td><td className="px-4 py-3.5 text-xs text-[#777883]">{customer.email || "-"}</td><td className="px-4 py-3.5 text-xs font-bold text-[#6957f5]">{Math.floor(Number(customer.points) || 0)}</td><td className="px-4 py-3.5"><Badge tone={customer.is_active === false ? "neutral" : "green"}>{customer.is_active === false ? "Inactive" : "Active"}</Badge></td><td className="px-2 py-3.5"><div className="flex items-center justify-end gap-1"><IconButton label="View customer" onClick={() => openDetail(customer)}><Eye size={15} /></IconButton><IconButton label={customer.is_active === false ? "Activate" : "Deactivate"} onClick={() => setToggleTarget({ id: customer.id, name: customer.name, activate: customer.is_active === false })}>{customer.is_active === false ? <ToggleLeft size={15} /> : <ToggleRight size={15} />}</IconButton><IconButton label="Edit customer" onClick={() => { setFormEditing(customer); setForm({ name: customer.name, phone: customer.phone || "", email: customer.email || "", notes: customer.notes || "" }); }}><Edit3 size={15} /></IconButton><IconButton label="Delete customer" onClick={() => setDeleteTarget(customer)}><Trash2 size={15} /></IconButton></div></td></tr>)}</tbody></table></div></div>{form && <Modal open onClose={() => { setForm(null); setFormEditing(null); }} title={formEditing ? `Edit ${formEditing.name}` : "Add a customer"} description="Customer records are shared across your stores." width="max-w-[480px]"><div className="space-y-4"><Field label="Name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /><div className="grid gap-4 sm:grid-cols-2"><Field label="Phone" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} /><Field label="Email" type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></div><Field label="Notes" value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} /></div><div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={() => { setForm(null); setFormEditing(null); }}>Cancel</Button><Button className="flex-1" onClick={saveCustomer} disabled={!form.name.trim()}>{formEditing ? "Save changes" : "Add customer"} <Check size={15} /></Button></div></Modal>}{detailCustomer && <Modal open onClose={() => setDetailCustomer(null)} title={detailCustomer.name} description={`Since ${new Date(detailCustomer.created_at).toLocaleDateString()}`} width="max-w-[640px]"><div className="grid gap-3 sm:grid-cols-3">{[{ label: "Orders", value: detail?.orders_count ?? 0 }, { label: "Total spent", value: formatCurrencyAmount(Number(detail?.total_spent ?? 0), baseCurrency) }, { label: "Points", value: Math.floor(Number(detailCustomer.points) || 0) }].map((stat, i) => <div key={i} className="rounded-xl border border-[#e9e9ef] bg-[#fafafd] p-4"><p className="text-[10px] font-semibold text-[#92939d]">{stat.label}</p><p className="mt-1 text-xl font-extrabold tracking-[-.04em]">{stat.value}</p></div>)}</div><div className="mt-4 rounded-xl border border-[#e9e9ef] p-4"><div className="flex items-center justify-between"><span className="text-xs font-extrabold">Adjust points</span></div><div className="mt-3 flex flex-wrap items-center gap-2"><input type="number" defaultValue="10" id="pts-delta" className="h-9 w-24 rounded-lg border border-[#e1e1e8] bg-white px-2 text-xs outline-none" /><Button size="xs" onClick={() => adjustPoints(Number(document.getElementById("pts-delta")?.value || 0) || 0)}><Plus size={13} /> Add</Button><Button variant="outline" size="xs" onClick={() => adjustPoints(-1 * (Number(document.getElementById("pts-delta")?.value || 0) || 0))}><Minus size={13} /> Remove</Button></div></div><div className="mt-5"><h3 className="text-sm font-extrabold">Order history</h3><div className="mt-3 space-y-2">{!detail ? <p className="py-8 text-center text-xs text-[#92939d]">Loading...</p> : detail.orders.length === 0 ? <p className="py-8 text-center text-xs text-[#92939d]">No orders yet.</p> : detail.orders.map((order) => <div key={order.id} className="flex items-center gap-3 rounded-xl border border-[#e9e9ef] p-3"><div className="min-w-0 flex-1"><p className="text-xs font-extrabold">{order.order_number}</p><p className="mt-0.5 text-[10px] text-[#999aa4]">{new Date(order.created_at).toLocaleString()}</p></div><Badge tone={order.status === "paid" ? "green" : order.status === "refunded" ? "violet" : "yellow"}>{order.status.replaceAll("_", " ")}</Badge><p className="text-xs font-extrabold">{formatCurrencyAmount(Number(order.total), baseCurrency)}</p><IconButton label="View receipt" onClick={() => onOpenOrder?.(order)}><Eye size={15} /></IconButton></div>)}</div></div><div className="mt-5 flex justify-end"><Button onClick={() => setDetailCustomer(null)}>Close</Button></div></Modal>}{toggleTarget && <ConfirmDialog open title={toggleTarget.activate ? `Activate ${toggleTarget.name}?` : `Deactivate ${toggleTarget.name}?`} message={toggleTarget.activate ? "This customer can be attached to new sales again." : "Deactivated customers can no longer be attached to new sales, but history stays intact."} confirmLabel={toggleTarget.activate ? "Activate" : "Deactivate"} onConfirm={performToggle} onCancel={() => setToggleTarget(null)} />}{deleteTarget && <ConfirmDialog open title={`Delete ${deleteTarget.name}?`} message="This permanently removes the customer." confirmLabel="Delete customer" onConfirm={performDelete} onCancel={() => setDeleteTarget(null)} />}</div>;}

function RefundModal({ order, token, storeId, baseCurrency = "USD", taxRate = 10, taxInclusive = false, onClose, onDone, notify }) {  const [lines, setLines] = useState([]);
const [loadingRefunds, setLoadingRefunds] = useState(true);
const [submitting, setSubmitting] = useState(false);
const [method, setMethod] = useState("cash");
const [reason, setReason] = useState("");
const [error, setError] = useState("");  useEffect(() => { let active = true; (async () => { try { const refunds = await api.orderRefunds(token, storeId, order.id); if (!active) return; const refunded = {}; for (const refund of refunds) for (const item of refund.items) refunded[item.product_id] = (refunded[item.product_id] || 0) + item.quantity; setLines(order.items.map((item) => { const remaining = item.quantity - (refunded[item.product_id] || 0); return { product_id: item.product_id, product_name: item.product_name, sku: item.sku, unit_price: Number(item.unit_price), max: Math.max(0, remaining), qty: Math.max(0, remaining) }; })); } catch (requestError) { if (active) setError(requestError.message || "Could not load refundable lines"); } finally { if (active) setLoadingRefunds(false); } })(); return () => { active = false; }; }, [order.id, token, storeId]);  const changeQty = (productId, value) => setLines((current) => current.map((line) => line.product_id === productId ? { ...line, qty: Math.max(0, Math.min(line.max, value)) } : line));  const selected = lines.filter((line) => line.qty > 0);  const subtotal = selected.reduce((sum, line) => sum + line.unit_price * line.qty, 0);  const tax = taxInclusive ? 0 : Number(((subtotal * (Number(taxRate) || 10)) / 100).toFixed(2));  const total = Number((subtotal + tax).toFixed(2));  const submit = async () => { setSubmitting(true); setError(""); try { const result = await api.refundOrder(token, storeId, order.id, { method, reason: reason.trim() || null, items: selected.map((line) => ({ product_id: line.product_id, quantity: line.qty })) }); notify(`Refunded ${formatCurrencyAmount(Number(result.total), result.currency_code)} on ${order.order_number}`); onDone?.(result); } catch (requestError) { setError(requestError.message || "Refund failed"); } finally { setSubmitting(false); } };  return <Modal open onClose={onClose} title={`Refund ${order.order_number}`} description="Return items to stock and record the money back to the customer." width="max-w-[560px]">{loadingRefunds ? <div className="py-10 text-center text-xs text-[#92939d]">Checking for existing refunds...</div> : <div><div className="mt-3 space-y-2">{lines.map((line) => <div key={line.product_id} className="rounded-xl border border-[#e7e7ed] bg-white p-3"><div className="flex items-center gap-3"><div className="min-w-0 flex-1"><p className="truncate text-xs font-extrabold">{line.product_name}</p><p className="mt-1 text-[10px] text-[#999aa4]">{formatCurrencyAmount(line.unit_price, baseCurrency)} each · {line.max} refundable</p></div>{line.max > 0 ? <div className="flex items-center gap-2 rounded-lg bg-[#f3f3f6] p-0.5"><button onClick={() => changeQty(line.product_id, line.qty - 1)} disabled={submitting} className="flex h-7 w-7 items-center justify-center rounded-md text-[#72737d] hover:bg-white"><Minus size={12} /></button><span className="w-5 text-center text-xs font-extrabold">{line.qty}</span><button onClick={() => changeQty(line.product_id, line.qty + 1)} disabled={submitting || line.qty >= line.max} className="flex h-7 w-7 items-center justify-center rounded-md bg-white text-[#6957f5] shadow-sm"><Plus size={12} /></button></div> : <span className="text-[10px] font-semibold text-[#9a9ba4]">Fully refunded</span>}</div></div>)}</div><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Refund method</span><Dropdown value={method} onChange={(v) => setMethod(v)} options={[{ value: "cash", label: "Cash" }, { value: "card", label: "Card" }, { value: "original", label: "Original payment" }]} /></label><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Reason (optional)</span><input value={reason} onChange={(event) => setReason(event.target.value)} className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm outline-none" /></label></div><div className="mt-4 rounded-xl bg-[#f7f7fa] p-4 text-xs"><div className="flex justify-between text-[#777883]"><span>Items refunded</span><span>{formatCurrencyAmount(subtotal, baseCurrency)}</span></div>{!taxInclusive && <div className="mt-2 flex justify-between text-[#777883]"><span>Tax ({(Number(taxRate) || 10)}%)</span><span>{formatCurrencyAmount(tax, baseCurrency)}</span></div>}<div className="mt-3 flex justify-between border-t border-[#e3e3ea] pt-3 text-sm font-extrabold"><span>Total to refund</span><span>{formatCurrencyAmount(total, baseCurrency)}</span></div></div>{error && <p className="mt-3 rounded-xl border border-[#ffd7d2] bg-[#fff5f3] px-3 py-2 text-xs text-[#c2564b]">{error}</p>}<div className="mt-5 flex gap-2"><Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button><Button variant="danger" className="flex-1" disabled={submitting || selected.length === 0} onClick={submit}>{submitting ? "Processing..." : `Refund ${formatCurrencyAmount(total, baseCurrency)}`} <RotateCcw size={14} /></Button></div></div>}</Modal>;}

export {
  PRODUCT_COLORS,
  POSPaymentModal,
  LivePOSView,
  ScanModal,
  HoldCartModal,
  HeldOrdersModal,
  PaymentModal,
  LiveOrdersWithReceipt,
  CustomerPickerModal,
  CustomerFormModal,
  CustomerDetailModal,
  LoyaltySettingsModal,
  LiveCustomersView,
  RefundModal,
};
